export function SkillsetDashboard() {
	const [value, setValue] = useState<string>('1');

	const dataSouce = () => {
		switch (value) {
			case '2':
				return frameworks;
			case '3':
				return databases;
			default:
				return pureLanguages;
		}
	};

	const valueFormat = (value: number) => {
		switch (true) {
			case value <= 250:
				return 'Novice';
			case value <= 500:
				return 'Intermediate';
			case value <= 750:
				return 'Advanced';
			default:
				return 'Expert';
		}
	};

	return (
		<Card className='max-w-full'>
			<Flex>
				<Title className='font-bold'>Skillset</Title>
				<Dropdown
					className='w-3/5'
					value={value}
					onValueChange={setValue}
					placeholder='Render mode'
				>
					<DropdownItem
						value='1'
						text='Pure Languages'
						icon={LanguageIcon}
					/>
					<DropdownItem
						value='2'
						text='Frameworks and Libraries'
						icon={FrameworkIcon}
					/>
					<DropdownItem
						value='3'
						text='Data Hosting and Storage'
						icon={DatabaseIcon}
					/>
				</Dropdown>
			</Flex>
			<BarList
				data={dataSouce()}
				valueFormatter={valueFormat}
				className='mt-2'
			/>
		</Card>
	);
}
